import sys
import math

N, fifty, hundred, K = 0, 0, 0, 0
memo = None
memo2 = None
MOD = int(1e9 + 7)
comb = None

def solve(t, f, h):
    global memo, fifty, hundred, K
    if f + h == 0:
        return 0
    if memo[t][f][h] != -1:
        return memo[t][f][h]
    if t == 1:
        if f < fifty:
            res = solve(0, f + 1, h)
        else:
            res = solve(0, f, h + 1)
        return res
    answer = int(1e6)
    for i in range(f + 1):
        if i * 50 > K:
            break
        j = min((K - i * 50) // 100, h)
        totalWeight = i * 50 + j * 100
        if ((fifty - f + i > 0 and totalWeight > 50) or
            (hundred - h + j > 1 and totalWeight > 100) or
            (i == fifty and j == hundred)):
            continue
        answer = min(answer, solve(1, f - i, h - j))
    memo[t][f][h] = answer + 1
    return memo[t][f][h]

def solve2(t, f, h, r):
    global memo2, fifty, hundred, K
    if r == 0 and f == 0 and h == 0:
        return 1
    if r == 0:
        return 0
    if memo2[t][f][h][r] != -1:
        return memo2[t][f][h][r]
    res = 0
    if t == 1:
        for i in range(fifty - f + 1):
            if i * 50 > K:
                break
            for j in range(hundred - h + 1):
                if i == 0 and j == 0:
                    continue
                weightSum = i * 50 + j * 100
                if weightSum > K:
                    break
                res += (nCk(fifty - f, i) * nCk(hundred - h, j) % MOD) * solve2(0, f + i, h + j, r - 1)
                res %= MOD
    else:
        for i in range(f + 1):
            if i * 50 > K:
                break
            for j in range(h + 1):
                if i == 0 and j == 0:
                    continue
                weightSum = i * 50 + j * 100
                if weightSum > K:
                    break
                res += (nCk(f, i) * nCk(h, j) % MOD) * solve2(1, f - i, h - j, r - 1)
                res %= MOD
    memo2[t][f][h][r] = res
    return res

def nCk(n, k):
    global comb
    if n < k:
        return 0
    if k == 0 or n == k:
        return 1
    if comb[n][k] != -1:
        return comb[n][k]
    if n - k < k:
        return nCk(n, n - k)
    comb[n][k] = (n * nCk(n - 1, k - 1) * pow(k, MOD - 2, MOD)) % MOD
    return comb[n][k]

def main():
    global N, fifty, hundred, K, memo, memo2, comb
    input_data = sys.stdin.read().strip().split()
    totalItems = int(input_data[0])
    K = int(input_data[1])
    items = list(map(int, input_data[2:]))

    for v in items:
        if v == 50:
            fifty += 1
        elif v == 100:
            hundred += 1

    memo = [[[ -1 for _ in range(hundred + 1)] for _ in range(fifty + 1)] for _ in range(2)]
    comb = [[-1 for _ in range(101)] for _ in range(101)]
    for i in range(101):
        for j in range(101):
            comb[i][j] = -1

    minSteps = solve(0, fifty, hundred)
    if minSteps >= int(1e6):
        print(-1)
        print(0)
    else:
        memo2 = [[[[ -1 for _ in range(minSteps + 1)] for _ in range(hundred + 1)] for _ in range(fifty + 1)] for _ in range(2)]
        print(minSteps)
        print(solve2(0, fifty, hundred, minSteps))

if __name__ == "__main__":
    main()

